/**
 * OpenCode Hook Adapter
 * Handles OpenCode's Anthropic-compatible hook data
 */

import { SupportedAgent } from '../../supported-agents';
import {
  UniversalAgentSessionEvent,
  NormalizedEventType,
} from '../../types/UniversalAgentSessionEvent';
import { extractFilePathsFromToolInput, getFileOperation } from '../../types/PathNormalization';
import { AgentEventProcessor } from '../AgentEventProcessor';

import type { OpenCodeHookInput } from './types';
import {
  isOpenCodeToolCall,
  isOpenCodeFileRead,
  isOpenCodeFileEdited,
  isOpenCodeWebAccess,
  isOpenCodeSessionStop,
} from './types';
// Helper to safely extract values
function getString(value: unknown, defaultValue: string = ''): string {
  return typeof value === 'string' ? value : defaultValue;
}

function getNumber(value: unknown, defaultValue: number = 0): number {
  return typeof value === 'number' ? value : defaultValue;
}

export class OpenCodeEventProcessor implements AgentEventProcessor<OpenCodeHookInput> {
  /**
   * Normalize OpenCode hook data into standardized format
   * OpenCode uses Anthropic-compatible hooks, so this is similar to Claude
   */
  normalize(rawData: OpenCodeHookInput): UniversalAgentSessionEvent {
    const timestamp = getNumber((rawData as any).timestamp, Date.now());
    let eventType: NormalizedEventType = 'unknown';
    let toolName: string | undefined;
    let toolInput: unknown | undefined;
    let toolOutput: unknown | undefined;
    const data: Record<string, unknown> = {};

    // OpenCode uses Anthropic-compatible hooks
    const hookEventName = (rawData as any).hook_event_name;

    if (hookEventName) {
      switch (hookEventName) {
        case 'PreToolUse':
          eventType = 'pre-tool-use';
          toolName = (rawData as any).tool_name;
          toolInput = (rawData as any).tool_input;
          break;

        case 'PostToolUse':
          eventType = 'post-tool-use';
          toolName = (rawData as any).tool_name;
          toolInput = (rawData as any).tool_input;
          toolOutput = (rawData as any).tool_response;
          break;

        case 'Notification':
          eventType = 'notification';
          data.message = (rawData as any).message;
          break;

        case 'UserPromptSubmit':
          eventType = 'user-prompt-submit';
          data.prompt = (rawData as any).prompt;
          break;

        case 'Stop':
          eventType = 'stop';
          data.stopHookActive = (rawData as any).stop_hook_active;
          break;

        case 'SubagentStop':
          eventType = 'subagent-stop';
          data.stopHookActive = (rawData as any).stop_hook_active;
          break;

        case 'PreCompact':
          eventType = 'pre-compact';
          data.trigger = (rawData as any).trigger;
          data.customInstructions = (rawData as any).custom_instructions;
          break;

        case 'SessionStart':
          eventType = 'session-start';
          data.source = (rawData as any).source;
          break;
      }
    } else {
      // Fallback for old format (if any)
      if (isOpenCodeSessionStop(rawData)) {
        eventType = 'stop';
      } else if (isOpenCodeFileRead(rawData)) {
        eventType = 'pre-tool-use';
        toolName = 'Read';
        toolInput = { file_path: (rawData as any).tool_input?.file_path };
      } else if (isOpenCodeFileEdited(rawData)) {
        eventType = 'post-tool-use';
        toolName = 'Edit';
        toolInput = (rawData as any).tool_input;
      } else if (isOpenCodeWebAccess(rawData)) {
        eventType = 'post-tool-use';
        toolName = 'WebFetch';
        toolInput = (rawData as any).tool_input;
      } else if (isOpenCodeToolCall(rawData)) {
        eventType = 'pre-tool-use';
        toolName = (rawData as any).tool_name;
        toolInput = (rawData as any).tool_input;
      }
    }

    // Build normalized event
    const normalized: UniversalAgentSessionEvent = {
      eventType,
      sessionId: getString(
        (rawData as any).session_id,
        process.env.OPENCODE_SESSION_ID || `opencode-${Date.now()}`,
      ),
      workingDirectory: getString(
        (rawData as any).cwd || (rawData as any).working_directory,
        process.env.OPENCODE_WORKING_DIRECTORY || process.cwd(),
      ),
      transcriptPath: getString((rawData as any).transcript_path),
      timestamp,
      provider: SupportedAgent.OPENCODE,
      raw: rawData,
    };

    // Add optional fields
    if (toolName) normalized.toolName = toolName;
    if (toolInput !== undefined) normalized.toolInput = toolInput;
    if (toolOutput !== undefined) normalized.toolOutput = toolOutput;
    if (Object.keys(data).length > 0) normalized.data = data;

    // Extract file paths for tool events
    if (toolName && toolInput) {
      const extractedPaths = extractFilePathsFromToolInput(toolName, toolInput);
      if (extractedPaths.length > 0) {
        // Set operation at root level
        normalized.operation = getFileOperation(toolName);

        // Set raw file paths for later normalization
        normalized.rawFilePaths = extractedPaths;
      }
    }

    return normalized;
  }

  /**
   * Extract tool information if this is a tool event
   * @deprecated Use normalized event's toolName and toolInput
   */
  extractToolInfo(event: any): { toolName: string; toolInput: unknown } | null {
    if (event.tool_name) {
      return {
        toolName: event.tool_name,
        toolInput: event.tool_input || {},
      };
    }
    return null;
  }
}
